16	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
17	//
18	//	{"version":1,
19	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
20	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
21	//	 "settlements":[{...一笔成功结算及其当时费率...}],
22	//	 "refunds":[{...一笔成功全额退款...}],
23	//	 "checksum":"<sha256 of the document without checksum>"}
24	//
25	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
26	// checksum 覆盖截断、比特翻转与所有语义编辑。
27	//
28	// refunds 字段缺省（旧版账本没有该字段）即视为空列表：旧文件可直接打开；
29	// 只要账本没有发生退款，写回时该字段继续缺省，读取旧账本不会改写文件。
30	//
31	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
32	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
33	// 不会出现“扣款/退款无记录”或“记录未改余额”的中间状态。
34	const ledgerVersion = 1
35	
36	// 结算结果状态，与命令行输出一一对应，可分别识别。
37	const (
38		StatusSettled         = "settled"              // 成功扣款
39		StatusDuplicate       = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算/原退款，不再入账
40		StatusConflict        = "conflict"             // 编号冲突：编号已成功但字段或费率/目标或原因不同
41		StatusState           = "state_error"          // 非 pending
42		StatusFunds           = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
43		StatusInvalid         = "invalid_parameter"
44		StatusStorage         = "storage_error"
45		StatusRefundSuccess   = "refunded"         // 成功全额退回
46		StatusNotFound        = "not_found"        // 退款目标结算不存在（含原付款只曾失败）
47		StatusAlreadyRefunded = "already_refunded" // 原付款已被其他退款编号全额退回
48	)
49	
50	// 拒绝原因。
51	const (
52		reasonEmptyID         = "intent id must not be empty"
53		reasonEmptyAccount    = "account must not be empty"
54		reasonEmptyAsset      = "asset must not be empty"
55		reasonBadAmount       = "amount must be a positive int64"
56		reasonOverflow        = "amount plus fee overflows int64"
57		reasonNotPending      = "intent is not pending"
58		reasonFunds           = "insufficient balance for amount plus fee"
59		reasonDuplicate       = "duplicate settlement attempt"
60		reasonConflict        = "settlement id conflicts with a different request"
61		reasonEmptyRefundID   = "refund id must not be empty"
62		reasonEmptySettlement = "settlement_id must not be empty"
63		reasonEmptyReason     = "refund reason must not be empty"
64		reasonSettlementGone  = "settlement %q not found"
65		reasonAlreadyRefunded = "settlement %q has already been refunded by %q"
66		reasonRefundConflict  = "refund id conflicts with a different request"
67		reasonDuplicateRefund = "duplicate refund attempt"
68	)
69	
70	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
71	type BalanceInit struct {
72		Account string `json:"account"`
73		Asset   string `json:"asset"`
74		Balance int64  `json:"balance"`
75	}
76	
77	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
78	type PaymentIntent struct {
79		ID        string `json:"id"`
80		Account   string `json:"account"`
81		Paymaster string `json:"paymaster"`
82		Asset     string `json:"asset"`
83		Amount    *int64 `json:"amount"`
84		Nonce     uint64 `json:"nonce"`
85		State     string `json:"state"`
86	}
87	
88	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表。
89	type FeeBatch struct {
90		FeeBps  int             `json:"fee_bps"`
91		Intents []PaymentIntent `json:"intents"`
92	}
93	
94	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
95	type Record struct {
96		ID        string `json:"id"`
97		Account   string `json:"account"`
98		Paymaster string `json:"paymaster"`
99		Asset     string `json:"asset"`
100		Amount    int64  `json:"amount"`
101		Nonce     uint64 `json:"nonce"`
102		FeeBps    int    `json:"fee_bps"`
103		Fee       int64  `json:"fee"`
104		Charged   int64  `json:"charged"`
105		Seq       int64  `json:"seq"`
106	}
107	
108	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
109	type ItemResult struct {
110		ID     string  `json:"id"`
111		Status string  `json:"status"`
112		Reason string  `json:"reason,omitempty"`
113		Record *Record `json:"record,omitempty"`
114	}
115	
116	// BatchResult 是一次提交的结果。空批次对应空 Results。
117	type BatchResult struct {
118		Results []ItemResult `json:"results"`
119	}
120	
121	// RefundRequest 是退款批次中的一项：退款编号、原付款编号、退款原因，三者均须非空。
122	type RefundRequest struct {
123		ID           string `json:"id"`
124		SettlementID string `json:"settlement_id"`
125		Reason       string `json:"reason"`
126	}
127	
128	// RefundBatch 是一次退款提交：有序的退款请求列表。
129	type RefundBatch struct {
130		Refunds []RefundRequest `json:"refunds"`
131	}
132	
133	// RefundRecord 是一笔成功全额退款留下的永久记录，按退款成功先后顺序保存。
134	// 退款金额与去向（账户/资产/总额）全部由原结算记录确定，因此一并冗余记录，
135	// 使每条退款都能脱离上下文自解释、可追溯原结算。
136	// AfterSeq 是退款落账时结算历史的长度：余额校验要求该结算在此时点之前发生。
137	type RefundRecord struct {
138		ID           string `json:"id"`
139		SettlementID string `json:"settlement_id"`
140		Reason       string `json:"reason"`
141		Account      string `json:"account"`
142		Asset        string `json:"asset"`
143		Amount       int64  `json:"amount"`
144		Fee          int64  `json:"fee"`
145		Charged      int64  `json:"charged"`
146		AfterSeq     int64  `json:"after_seq"`
147		Seq          int64  `json:"seq"`
148	}
149	
150	// RefundResult 是一项退款的处理结果。成功与幂等重复携带原付款编号、账户、
151	// 资产、退款总额与原因；失败只带状态与说明。
152	type RefundResult struct {
153		ID           string        `json:"id"`
154		Status       string        `json:"status"`
155		Reason       string        `json:"reason,omitempty"`
156		SettlementID string        `json:"settlement_id,omitempty"`
157		Account      string        `json:"account,omitempty"`
158		Asset        string        `json:"asset,omitempty"`
159		Charged      int64         `json:"charged,omitempty"`
160		Record       *RefundRecord `json:"record,omitempty"`
161	}
162	
163	// RefundBatchResult 是一次退款提交的结果，顺序与输入逐项对应。
164	type RefundBatchResult struct {
165		Results []RefundResult `json:"results"`
166	}
167	
168	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
169	type BalanceView struct {
170		Account string `json:"account"`
171		Asset   string `json:"asset"`
172		Balance int64  `json:"balance"`
173	}
174	
175	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
176	type Snapshot struct {
177		Balances    []BalanceView  `json:"balances"`
178		Settlements []Record       `json:"settlements"`
179		Refunds     []RefundRecord `json:"refunds"`
180	}
181	
182	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
183	type LedgerError struct {
184		Kind    string
185		Message string
186	}
187	
188	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
189	
190	// 错误分类。
191	const (
192		ErrInvalid = "invalid_parameter"
193		ErrExists  = "ledger_exists"
194		ErrCorrupt = "corrupt_ledger"
195		ErrStorage = "storage_error"
196		ErrClosed  = "ledger_closed"
197		ErrNotInit = "ledger_not_initialized"
198	)
199	
200	func ledgerError(kind, format string, args ...any) error {
201		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
202	}
203	
204	// KindOf 返回错误的分类；非账本错误按存储错误处理。
205	func KindOf(err error) string {
206		var le *LedgerError
207		if errors.As(err, &le) {
208			return le.Kind
209		}
210		return ErrStorage
211	}
212	
213	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
214	// 内存状态必须回滚到该项执行之前。仅用于测试。
215	type FailWriter interface {
216		FailNextPersist() bool
217	}
218	
219	type balanceKey struct {
220		account string
221		asset   string
222	}
223	
224	type ledgerState struct {
225		Version     int
226		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
227		Balances    map[balanceKey]int64 // 当前余额
228		Settlements []Record
229		Refunds     []RefundRecord
230	}
231	
232	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
233	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
234	// 且无退款的账本写回时继续省略该字段。
235	type unsignedDoc struct {
236		Version     int            `json:"version"`
237		Initial     []BalanceView  `json:"initial_balances"`
238		Balances    []BalanceView  `json:"balances"`
239		Settlements []Record       `json:"settlements"`
240		Refunds     []RefundRecord `json:"refunds,omitempty"`
241	}
242	
243	type signedDoc struct {
244		unsignedDoc
245		Checksum string `json:"checksum"`
246	}
247	
248	func balanceList(m map[balanceKey]int64) []BalanceView {
249		out := make([]BalanceView, 0, len(m))
250		for k, v := range m {
251			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
252		}
253		sortBalances(out)
254		return out
255	}
256	
257	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
258		out := make(map[balanceKey]int64, len(list))
259		for i, b := range list {
260			if b.Account == "" || b.Asset == "" {
261				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
262			}
263			if b.Balance < 0 {
264				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
265			}
266			k := balanceKey{b.Account, b.Asset}
267			if _, dup := out[k]; dup {
268				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
269			}
270			out[k] = b.Balance
271		}
272		return out, nil
273	}
274	
275	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
276	func (s *ledgerState) MarshalJSON() ([]byte, error) {
277		settlements := s.Settlements
278		if settlements == nil {
279			settlements = []Record{}
280		}
281		doc := unsignedDoc{
282			Version:     s.Version,
283			Initial:     balanceList(s.Initial),
284			Balances:    balanceList(s.Balances),
285			Settlements: settlements,
286			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
287		}
288		payload, err := json.Marshal(doc)
289		if err != nil {
290			return nil, err
291		}
292		sum := checksumHex(payload)
293		out := make([]byte, 0, len(payload)+len(sum)+16)
294		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
295		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
296		return out, nil
297	}
298	
299	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
300	func (s *ledgerState) UnmarshalJSON(data []byte) error {
301		var doc signedDoc
302		if err := json.Unmarshal(data, &doc); err != nil {
303			return err
304		}
305		if doc.Checksum == "" {
306			return ledgerError(ErrCorrupt, "missing checksum")
307		}
308		payload, err := json.Marshal(doc.unsignedDoc)
309		if err != nil {
310			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
311		}
312		if got := checksumHex(payload); got != doc.Checksum {
313			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
314		}
315		if doc.Version != ledgerVersion {
316			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
317		}
318		initial, err := balanceMap(doc.Initial)
319		if err != nil {
320			return err
321		}
322		current, err := balanceMap(doc.Balances)
323		if err != nil {
324			return err
325		}
326		records := doc.Settlements
327		if records == nil {
328			records = []Record{}
329		}
330		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
331		if refunds == nil {
332			refunds = []RefundRecord{}
333		}
334		if err := validateAndReplay(initial, current, records, refunds); err != nil {
335			return err
336		}
337		s.Version = doc.Version
338		s.Initial = initial
339		s.Balances = current
340		s.Settlements = records
341		s.Refunds = refunds
342		return nil
343	}
344	
345	func decodeState(data []byte) (*ledgerState, error) {
346		var state ledgerState
347		if err := json.Unmarshal(data, &state); err != nil {
348			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
349				return nil, err
350			}
351			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
352		}
353		return &state, nil
354	}
355	
356	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
357	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
358	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
359	func CreateLedger(path string, init []BalanceInit) error {
360		if err := validateInitial(init); err != nil {
361			return err
362		}
363		abs, err := filepath.Abs(path)
364		if err != nil {
365			return ledgerError(ErrStorage, "resolve path: %v", err)
366		}
367	
368		openMu.Lock()
369		defer openMu.Unlock()
370	
371		if _, err := os.Stat(abs); err == nil {
372			return ledgerError(ErrExists, "ledger already exists at %s", abs)
373		} else if !errors.Is(err, os.ErrNotExist) {
374			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
375		}
376		if openRegistry[abs] != nil {
377			return ledgerError(ErrExists, "ledger is already initialized in this process")
378		}
379	
380		state := &ledgerState{
381			Version:     ledgerVersion,
382			Initial:     make(map[balanceKey]int64, len(init)),
383			Balances:    make(map[balanceKey]int64, len(init)),
384			Settlements: []Record{},
385			Refunds:     []RefundRecord{},
386		}
387		for _, b := range init {
388			k := balanceKey{b.Account, b.Asset}
389			state.Initial[k] = b.Balance
390			state.Balances[k] = b.Balance
391		}
392		if err := atomicWrite(abs, state); err != nil {
393			return err
394		}
395		openRegistry[abs] = &registryEntry{state: state}
396		return nil
397	}
398	
399	func validateInitial(init []BalanceInit) error {
400		seen := map[balanceKey]bool{}
401		for i, b := range init {
402			if b.Account == "" {
403				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
404			}
405			if b.Asset == "" {
406				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
407			}
408			if b.Balance < 0 {
409				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
410			}
411			k := balanceKey{b.Account, b.Asset}
412			if seen[k] {
413				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
414			}
415			seen[k] = true
416		}
417		return nil
418	}
419	
420	// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
421	// 返回共享同一状态与互斥锁的实例，因此并发提交按同一本账本串行化。
422	type Ledger struct {
423		path string
424		reg  *registryEntry
425		open bool
426	}
427	
428	type registryEntry struct {
429		mu       sync.Mutex // 保护 state；整个批次串行持有
430		state    *ledgerState
431		refs     int        // 打开的句柄数
432		ops      int        // 正在执行的 Submit/Query 数
433		failHook FailWriter // 仅测试注入
434	}
435	
436	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
437	// 调用方必须持有 openMu。
438	func tryEvict(path string, reg *registryEntry) {
439		if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
440			delete(openRegistry, path)
441		}
442	}
443	
444	var (
445		openMu       sync.Mutex
446		openRegistry = map[string]*registryEntry{}
447	)
448	
449	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
450	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
451	func Open(path string) (*Ledger, error) {
452		abs, err := filepath.Abs(path)
453		if err != nil {
454			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
455		}
456	
457		openMu.Lock()
458		defer openMu.Unlock()
459	
460		if reg := openRegistry[abs]; reg != nil {
461			reg.refs++
462			return &Ledger{path: abs, reg: reg, open: true}, nil
463		}
464	
465		data, err := os.ReadFile(abs)
466		if err != nil {
467			if errors.Is(err, os.ErrNotExist) {
468				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
469			}
470			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
471		}
472		if len(bytes.TrimSpace(data)) == 0 {
473			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
474		}
475		dec := json.NewDecoder(bytes.NewReader(data))
476		var rawDoc json.RawMessage
477		if err := dec.Decode(&rawDoc); err != nil {
478			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
479		}
480		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
481		if tok, err := dec.Token(); err != io.EOF {
482			if err == nil {
483				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
484			}
485			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
486		}
487		state, err := decodeState(rawDoc)
488		if err != nil {
489			return nil, err
490		}
491	
492		reg := &registryEntry{state: state, refs: 1}
493		openRegistry[abs] = reg
494		return &Ledger{path: abs, reg: reg, open: true}, nil
495	}
496	
497	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
498	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
499	// 从磁盘重新加载而丢失正在写入的状态。
500	func (l *Ledger) Close() error {
501		openMu.Lock()
502		defer openMu.Unlock()
503		if !l.open {
504			return nil
505		}
506		l.open = false
507		l.reg.refs--
508		tryEvict(l.path, l.reg)
509		return nil
510	}
511	
512	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
513	func (l *Ledger) beginOp() error {
514		openMu.Lock()
515		defer openMu.Unlock()
516		if !l.open {
517			return ledgerError(ErrClosed, "ledger handle is closed")
518		}
519		l.reg.ops++
520		return nil
521	}
522	
523	func (l *Ledger) endOp() {
524		openMu.Lock()
525		defer openMu.Unlock()
526		l.reg.ops--
527		tryEvict(l.path, l.reg)
528	}
529	
530	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
531	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
532	// 拆成商和余数两部分即可在 int64 内精确完成。
533	func feeFor(amount int64, feeBps int) int64 {
534		hi := amount / 10000
535		lo := amount % 10000
536		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
537	}
538	
539	func validateIntent(it PaymentIntent) (int64, string, bool) {
540		if it.ID == "" {
541			return 0, reasonEmptyID, false
542		}
543		if it.Account == "" {
544			return 0, reasonEmptyAccount, false
545		}
546		if it.Asset == "" {
547			return 0, reasonEmptyAsset, false
548		}
549		if it.Amount == nil || *it.Amount <= 0 {
550			return 0, reasonBadAmount, false
551		}
552		return *it.Amount, "", true
553	}
554	
555	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
556	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
557	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
558	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
559		if err := l.beginOp(); err != nil {
560			return nil, err
561		}
562		defer l.endOp()
563		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
564			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
565		}
566		out := &BatchResult{Results: make([]ItemResult, 0, len(batch.Intents))}
567	
568		l.reg.mu.Lock()
569		defer l.reg.mu.Unlock()
570	
571		for i := range batch.Intents {
572			it := &batch.Intents[i]
573			res := ItemResult{ID: it.ID}
574	
575			// 1. 参数校验。未通过的编号不占用去重资格。
576			amount, reason, ok := validateIntent(*it)
577			if !ok {
578				res.Status = StatusInvalid
579				res.Reason = reason
580				out.Results = append(out.Results, res)
581				continue
582			}
583	
584			// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
585			//    任一不同则编号冲突。两者都不再扣款、不改原记录。
586			//    本批次内先成功的同编号项也在此被看到。
587			if rec, exists := l.findRecord(it.ID); exists {
588				if sameRequest(rec, it, amount, batch.FeeBps) {
589					cp := rec
590					res.Status = StatusDuplicate
591					res.Reason = reasonDuplicate
592					res.Record = &cp
593				} else {
594					res.Status = StatusConflict
595					res.Reason = reasonConflict
596				}
597				out.Results = append(out.Results, res)
598				continue
599			}
600	
601			// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
602			if it.State != "" && it.State != "pending" {
603				res.Status = StatusState
604				res.Reason = reasonNotPending
605				out.Results = append(out.Results, res)
606				continue
607			}
608	
609			// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
610			fee := feeFor(amount, batch.FeeBps)
611			if fee > math.MaxInt64-amount {
612				res.Status = StatusInvalid
613				res.Reason = reasonOverflow
614				out.Results = append(out.Results, res)
615				continue
616			}
617			total := amount + fee
618	
619			// 5. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
620			key := balanceKey{it.Account, it.Asset}
621			bal := l.reg.state.Balances[key]
622			if total > bal {
623				res.Status = StatusFunds
624				res.Reason = reasonFunds
625				out.Results = append(out.Results, res)
626				continue
627			}
628	
629			// 6. 先在内存生效，再原子持久化；保存失败回滚该项，不留成功记录。
630			rec := Record{
631				ID:        it.ID,
632				Account:   it.Account,
633				Paymaster: it.Paymaster,
634				Asset:     it.Asset,
635				Amount:    amount,
636				Nonce:     it.Nonce,
637				FeeBps:    batch.FeeBps,
638				Fee:       fee,
639				Charged:   total,
640				Seq:       int64(len(l.reg.state.Settlements)) + 1,
641			}
642			rollback := l.stage(key, bal-total, rec)
643			if err := l.persistLocked(); err != nil {
644				rollback()
645				res.Status = StatusStorage
646				res.Reason = err.Error()
647			} else {
648				cp := rec
649				res.Status = StatusSettled
650				res.Record = &cp
651			}
652			out.Results = append(out.Results, res)
653		}
654		return out, nil
655	}
656	
657	// stage 应用一笔扣款与记录，返回回滚函数（恢复该项执行前的余额与记录长度）。
658	func (l *Ledger) stage(key balanceKey, newBal int64, rec Record) func() {
659		oldBal, hadKey := l.reg.state.Balances[key]
660		oldLen := len(l.reg.state.Settlements)
661		l.reg.state.Balances[key] = newBal
662		l.reg.state.Settlements = append(l.reg.state.Settlements, rec)
663		return func() {
664			if hadKey {
665				l.reg.state.Balances[key] = oldBal
666			} else {
667				delete(l.reg.state.Balances, key)
668			}
669			l.reg.state.Settlements = l.reg.state.Settlements[:oldLen]
670		}
671	}
672	
673	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
674	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
675	// 结果与输入逐项对应，空批次返回空结果。
676	//
677	// 语义：
678	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
679	//     及原退款记录（不再入账）；任一不同返回 conflict。
680	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
681	//     该结算已被其他退款编号退回返回 refunded，不增加余额。
682	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
683	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
684	//   - 失败申请不占用退款编号，之后可修改原因或目标再提交。
685	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
686		if err := l.beginOp(); err != nil {
687			return nil, err
688		}
689		defer l.endOp()
690		out := &RefundBatchResult{Results: make([]RefundResult, 0, len(batch.Refunds))}
691	
692		l.reg.mu.Lock()
693		defer l.reg.mu.Unlock()
694	
695		for i := range batch.Refunds {
696			req := &batch.Refunds[i]
697			res := RefundResult{ID: req.ID}
698	
699			// 1. 参数校验：退款编号、原付款编号、原因三者都必须非空。
700			//    未通过的编号不占用退款资格。
701			if req.ID == "" {
702				res.Status = StatusInvalid
703				res.Reason = reasonEmptyRefundID
704				out.Results = append(out.Results, res)
705				continue
706			}
707			if req.SettlementID == "" {
708				res.Status = StatusInvalid
709				res.Reason = reasonEmptySettlement
710				out.Results = append(out.Results, res)
711				continue
712			}
713			if req.Reason == "" {
714				res.Status = StatusInvalid
715				res.Reason = reasonEmptyReason
716				out.Results = append(out.Results, res)
717				continue
718			}
719	
720			// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
721			//    任一不同则冲突。两者都不再入账。本批次内先成功的同编号项也在此可见。
722			if prior, exists := l.findRefund(req.ID); exists {
723				if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
724					cp := prior
725					res.Status = StatusDuplicate
726					res.Reason = prior.Reason
727					res.SettlementID = prior.SettlementID
728					res.Account = prior.Account
729					res.Asset = prior.Asset
730					res.Charged = prior.Charged
731					res.Record = &cp
732				} else {
733					res.Status = StatusConflict
734					res.Reason = reasonRefundConflict
735				}
736				out.Results = append(out.Results, res)
737				continue
738			}
739	
740			// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
741			target, exists := l.findRecord(req.SettlementID)
742			if !exists {
743				res.Status = StatusNotFound
744				res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
745				out.Results = append(out.Results, res)
746				continue
747			}
748	
749			// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
750			if prior, refunded := l.findRefundOfSettlement(req.SettlementID); refunded {
751				res.Status = StatusAlreadyRefunded
752				res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
753				out.Results = append(out.Results, res)
754				continue
755			}
756	
757			// 5. 全额退回原账户、原资产（amount 与当时手续费一并退回），
758			//    与退款记录在同一个原子写入中落盘；保存失败回滚该项。
759			rec := RefundRecord{
760				ID:           req.ID,
761				SettlementID: target.ID,
762				Reason:       req.Reason,
763				Account:      target.Account,
764				Asset:        target.Asset,
765				Amount:       target.Amount,
766				Fee:          target.Fee,
767				Charged:      target.Charged,
768				AfterSeq:     int64(len(l.reg.state.Settlements)),
769				Seq:          int64(len(l.reg.state.Refunds)) + 1,
770			}
771			key := balanceKey{target.Account, target.Asset}
772			bal := l.reg.state.Balances[key]
773			rollback := l.stageRefund(key, bal+target.Charged, rec)
774			if err := l.persistLocked(); err != nil {
775				rollback()
776				res.Status = StatusStorage
777				res.Reason = err.Error()
778			} else {
779				cp := rec
780				res.Status = StatusRefundSuccess
781				res.Reason = rec.Reason
782				res.SettlementID = rec.SettlementID
783				res.Account = rec.Account
784				res.Asset = rec.Asset
785				res.Charged = rec.Charged
786				res.Record = &cp
787			}
788			out.Results = append(out.Results, res)
789		}
790		return out, nil
791	}
792	
793	// stageRefund 应用一笔退款（余额增加 + 记录追加），返回回滚函数。
794	func (l *Ledger) stageRefund(key balanceKey, newBal int64, rec RefundRecord) func() {
795		oldBal, hadKey := l.reg.state.Balances[key]
796		oldLen := len(l.reg.state.Refunds)
797		l.reg.state.Balances[key] = newBal
798		l.reg.state.Refunds = append(l.reg.state.Refunds, rec)
799		return func() {
800			if hadKey {
801				l.reg.state.Balances[key] = oldBal
802			} else {
803				delete(l.reg.state.Balances, key)
804			}
805			l.reg.state.Refunds = l.reg.state.Refunds[:oldLen]
806		}
807	}
808	
809	func (l *Ledger) findRefund(id string) (RefundRecord, bool) {
810		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
811		for _, r := range l.stateView().Refunds {
812			if r.ID == id {
813				return r, true
814			}
815		}
816		return RefundRecord{}, false
817	}
818	
819	// findRefundOfSettlement 返回退回指定结算的那笔退款（每笔结算最多一笔）。
820	func (l *Ledger) findRefundOfSettlement(settlementID string) (RefundRecord, bool) {
821		for _, r := range l.stateView().Refunds {
822			if r.SettlementID == settlementID {
823				return r, true
824			}
825		}
826		return RefundRecord{}, false
827	}
828	
829	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
830	
831	func (l *Ledger) findRecord(id string) (Record, bool) {
832		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
833		for _, r := range l.stateView().Settlements {
834			if r.ID == id {
835				return r, true
836			}
837		}
838		return Record{}, false
839	}
840	
841	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
842	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
843		return r.Account == it.Account &&
844			r.Paymaster == it.Paymaster &&
845			r.Asset == it.Asset &&
846			r.Amount == amount &&
847			r.Nonce == it.Nonce &&
848			r.FeeBps == feeBps
849	}
850	
851	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
852	func (l *Ledger) Query() (*Snapshot, error) {
853		if err := l.beginOp(); err != nil {
854			return nil, err
855		}
856		defer l.endOp()
857		l.reg.mu.Lock()
858		defer l.reg.mu.Unlock()
859	
860		st := l.stateView()
861		bals := make([]BalanceView, 0, len(st.Balances))
862		for k, v := range st.Balances {
863			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
864		}
865		sortBalances(bals)
866		recs := make([]Record, len(st.Settlements))
867		copy(recs, st.Settlements)
868		refunds := make([]RefundRecord, len(st.Refunds))
869		copy(refunds, st.Refunds)
870		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
871	}
872	
873	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
874	func (l *Ledger) Balance(account, asset string) (int64, error) {
875		if err := l.beginOp(); err != nil {
876			return 0, err
877		}
878		defer l.endOp()
879		l.reg.mu.Lock()
880		defer l.reg.mu.Unlock()
881		return l.stateView().Balances[balanceKey{account, asset}], nil
882	}
883	
884	func sortBalances(bals []BalanceView) {
885		sort.Slice(bals, func(i, j int) bool {
886			if bals[i].Account != bals[j].Account {
887				return bals[i].Account < bals[j].Account
888			}
889			return bals[i].Asset < bals[j].Asset
890		})
891	}
892	
893	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
894	func (l *Ledger) persistLocked() error {
895		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
896			return ledgerError(ErrStorage, "injected write failure")
897		}
898		return atomicWrite(l.path, l.stateView())
899	}
900	
901	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
902	func SetFailHook(l *Ledger, fw FailWriter) {
903		l.reg.failHook = fw
904	}
