132	// ---- 批次逐项结果与顺序语义 ----
133	
134	func TestBatchOrderedIndependentResults(t *testing.T) {
135		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 2000}})
136		l := openOrFail(t, path)
137	
138		res, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
139			intent("p1", "aa", "usdc", 1500), // 扣 1504，成功，余 496
140			intent("p2", "aa", "usdc", 900),  // 需 902，不足
141			intent("p3", "aa", "usdc", 400),  // 需 401，成功，余 95
142			intent("p4", "zz", "usdc", 1),    // 账户/资产不存在，按不足处理
143		}})
144		if err != nil {
145			t.Fatal(err)
146		}
147		want := []string{StatusSettled, StatusFunds, StatusSettled, StatusFunds}
148		if got := statuses(res); fmt.Sprint(got) != fmt.Sprint(want) {
149			t.Fatalf("statuses=%v want %v", got, want)
