151		if bal, _ := l.Balance("aa", "usdc"); bal != 95 {
152			t.Fatalf("balance=%d want 95", bal)
153		}
154		snap, _ := l.Query()
155		if len(snap.Settlements) != 2 || snap.Settlements[0].ID != "p1" || snap.Settlements[1].ID != "p3" {
156			t.Fatalf("settlements not in success order: %+v", snap.Settlements)
157		}
