182	func TestInvalidItems(t *testing.T) {
183		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: math.MaxInt64}})
184		l := openOrFail(t, path)
185	
186		neg := int64(-5)
187		zero := int64(0)
188		batch := FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
189			{ID: "", Account: "aa", Asset: "usdc", Amount: i64p(1)},
190			{ID: "a", Account: "", Asset: "usdc", Amount: i64p(1)},
