	}
	defer l.Close()

	// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
	result, err := l.Submit(batch)
	if err != nil {
		return failWithError(stderr, err)
	}
	writeJSON(stdout, result)
	return 0
}

