		t.Fatal(err)
	}
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := l.ReconcileStatement([]StatementEntry{
		stmtPayment("p1", "aa", "usdc", 100, 0, 100),
		stmtPayment("ghost", "aa", "usdc", 1, 0, 1),
	}); err != nil {
		t.Fatal(err)
	}

	after, err := os.ReadFile(path)
	if err != nil {
