	}
	// max_seq 必须是数字。
	var maxSeq map[string]any
	if err := json.Unmarshal(raw["max_seq"], &maxSeq); err != nil {
		t.Fatal(err)
	}
	if _, ok := maxSeq["payments"].(float64); !ok {
		t.Fatalf("max_seq.payments is not a number: %v", maxSeq["payments"])
	}
}

