		Entries []struct {
			Status string `json:"status"`
		} `json:"entries"`
	}
	if err := json.Unmarshal([]byte(r.out), &rep); err != nil {
		t.Fatal(err)
	}
	if rep.Entries[0].Status != "matched" {
		t.Fatalf("file input reconcile: %+v", rep.Entries[0])
	}
}

