// 汇总金额用十进制整数字符串，累计超过 int64 仍精确。
func TestReconcileSummaryBigInt(t *testing.T) {
	path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: math.MaxInt64}})
	l := openReconcileLedger(t, path)
	// 多笔付款，累计 charged 超过 int64。
	const n = 10
	entries := make([]PaymentIntent, n)
	for i := 0; i < n; i++ {
		entries[i] = intent("p"+string(rune('a'+i)), "aa", "usdc", math.MaxInt64/2)
	}
	if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: entries}); err != nil {
		t.Fatal(err)
	}

	// 流水侧也构造同样多笔，累计超过 int64。
	stmt := make([]StatementEntry, n)
	for i := 0; i < n; i++ {
		stmt[i] = stmtPayment("p"+string(rune('a'+i)), "aa", "usdc", math.MaxInt64/2, 0, math.MaxInt64/2)
	}
	rep, err := l.ReconcileStatement(stmt)
	if err != nil {
		t.Fatal(err)
	}
	s := rep.Summary[0]
	// 账本侧累计 = n * (MaxInt64/2)，超过 int64。
	want := new(big.Int).Mul(big.NewInt(n), big.NewInt(math.MaxInt64/2))
	if s.Ledger.Charges != want.String() {
		t.Fatalf("ledger charges=%s want %s", s.Ledger.Charges, want.String())
	}
	if s.Statement.Charges != want.String() {
		t.Fatalf("statement charges=%s want %s", s.Statement.Charges, want.String())
	}
	if s.NetDiff != "0" {
		t.Fatalf("net_diff=%s want 0", s.NetDiff)
	}
}

