JSON
go run ./cmd/payflow submit -l "$D/l.json" <<'JSON'
{"fee_bps":30,"intents":[{"id":"p1","account":"aa-1","asset":"usdc","amount":1500}]}
JSON
go run ./cmd/payflow reconcile -l "$D/l.json" <<'JSON'
{"entries":[
  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1500,"fee":4,"charged":1504},
  {"kind":"payment","id":"ghost","account":"aa-1","asset":"usdc","amount":1,"fee":0,"charged":1}
]}
JSON
rm -rf "$D"

